import assert from 'node:assert/strict'
import test from 'node:test'
import { verifyAuthHeader } from '../../src/utils/auth.js'

// Generated by app/src/remoteNode/identity.ts with
// createMobileIdentity('alice', 'correct horse battery staple',
//   { now: 1700000000000, deviceLabel: 'golden-device' })
// buildMobileAuthHeader(identity, 'POST', '/api/download', 1700000000000)
const MOBILE_AUTH_GOLDEN =
  'dc1.eyJhZGRyZXNzIjoiMHgwMjNCMTBiNGU2OTE1ODA5NjZEMTYwRmJGNTBEY2U1NTk2QTk3RDRDIiwiZGV2aWNlUHVibGljS2V5IjoiN2Y4NmJlMTA1MDcxYjEzZmVhMmExY2Y2ZmE3ODMxMWZkMWU0YTViMTY4OThkMjU2NWVhNGQ3NzY5MzQ0OTBlOCIsImlzc3VlZEF0IjoxNzAwMDAwMDAwMDAwLCJleHBpcmVzQXQiOjE3MDI1OTIwMDAwMDB9.0xbdff4f34831f66d93feba70ba6a47450fec275f60ab04aadf10f51ecb51db76017438948eb950ff79243ab1ab3ca9e170a9e215e2282619eb18b37f04911a9181c,1700000000000,4Nynnjb2VRL6fnw6nDWqC2fJNo33Po3_yHL9YUFeuBYTkF_DFaYShF70EBetbFvoLoH6YNmb_NuPGSxHdA5zBQ'

test('server accepts the mobile device-signed request golden sample', () => {
  assert.deepEqual(
    verifyAuthHeader(MOBILE_AUTH_GOLDEN, 'POST', '/api/download', {
      now: 1_700_000_000_000,
    }),
    {
      ok: true,
      address: '0x023b10b4e691580966d160fbf50dce5596a97d4c',
      devicePublicKey:
        '7f86be105071b13fea2a1cf6fa78311fd1e4a5b16898d2565ea4d776934490e8',
    }
  )
})

test('mobile authorization stays bound to method and canonical path', () => {
  assert.equal(
    verifyAuthHeader(MOBILE_AUTH_GOLDEN, 'GET', '/api/download', {
      now: 1_700_000_000_000,
    }).ok,
    false
  )
  assert.equal(
    verifyAuthHeader(MOBILE_AUTH_GOLDEN, 'POST', '/proxy/api/download', {
      now: 1_700_000_000_000,
    }).ok,
    false
  )
})

test('the mobile golden certificate stops working after it expires', () => {
  const afterExpiry = 1_700_000_000_000 + 30 * 24 * 60 * 60 * 1000
  assert.equal(
    verifyAuthHeader(MOBILE_AUTH_GOLDEN, 'POST', '/api/download', {
      now: afterExpiry,
      maxAgeMs: Number.MAX_SAFE_INTEGER,
    }).error,
    'Device certificate expired'
  )
})
